// Ce webhook est exposé publiquement via Traefik. Un ticket créé ici est
// automatiquement ramassé par symphony-dispatcher (label agent:ok) puis exécuté
// avec accès push + PR sur le repo — donc pas de secret = exécution de code
// arbitraire par n'importe qui trouvant l'URL. D'où la vérification ici, avant
// même de parler à Linear.
const crypto = require('crypto');

const secret = $env.SYMPHONY_TICKET_SECRET;
if (!secret) {
  throw new Error('SYMPHONY_TICKET_SECRET manquant dans l\'environnement n8n');
}

const item = $input.first().json;
const headerSecret = (item.headers && item.headers['x-symphony-secret']) || '';

const expectedBuf = Buffer.from(secret, 'utf8');
const receivedBuf = Buffer.from(String(headerSecret), 'utf8');
const valid = expectedBuf.length === receivedBuf.length && crypto.timingSafeEqual(expectedBuf, receivedBuf);

if (!valid) {
  throw new Error('Secret invalide — requête rejetée');
}

const body = item.body || {};
const { title, description, labels } = body;

if (!title || !description) {
  throw new Error('Payload invalide — title et description sont obligatoires');
}

return [{
  json: {
    title,
    description,
    labels: Array.isArray(labels) && labels.length ? labels : ['agent:ok']
  }
}];

// Même logique de résolution par nom que symphony-dispatcher (jamais d'ID
// Linear en dur) : le ticket doit atterrir directement dans l'état "Ready"
// (LINEAR_STATE_READY) pour que le dispatcher le ramasse au prochain cron.
const payload = $('Vérifier secret + valider payload').first().json;
const resolved = $input.first().json;

const states = (resolved.data && resolved.data.team && resolved.data.team.states.nodes) || [];
const labelNodes = (resolved.data && resolved.data.team && resolved.data.team.labels.nodes) || [];

const wantedState = $env.LINEAR_STATE_READY || 'Ready';
const targetState = states.find((s) => s.name === wantedState);
if (!targetState) {
  throw new Error(`State "${wantedState}" introuvable sur l'équipe Linear.`);
}

const labelIds = payload.labels
  .map((name) => { const l = labelNodes.find((n) => n.name === name); return l ? l.id : null; })
  .filter(Boolean);

if (labelIds.length === 0) {
  throw new Error(`Aucun des labels demandés (${payload.labels.join(', ')}) n'existe sur le board Linear.`);
}

return [{
  json: {
    title: payload.title,
    description: payload.description,
    stateId: targetState.id,
    labelIds
  }
}];

const resp = $input.first().json;
const issue = resp.data && resp.data.issueCreate && resp.data.issueCreate.issue;
if (!issue) {
  throw new Error('issueCreate a échoué : ' + JSON.stringify(resp));
}
return [{ json: { success: true, identifier: issue.identifier, url: issue.url } }];
